1	// Content script: hosts the whole conversation inside the puzzle page — brain, voice,
2	// and hands in one place. Speech-only by design: what was said/heard goes to the page
3	// console for debugging (REQ-SPCH-007/008). Inert until asked (REQ-NFR-004): the only
4	// load-time side effects are registering the message listener and placing the toolbar
5	// toggle button (REQ-LIFE-012 — the spec's one carve-out). The session dies with the
6	// page (reload/navigation) — that is intended (REQ-LIFE-008).
7	
8	import { MSG } from '../shared/messages.js';
9	import { snapshot, isRuledWrong } from '../page-adapter/reader.js';
10	import { enterAnswer, clearEntry, keepAlive } from '../page-adapter/writer.js';
11	import { selectClue } from '../page-adapter/navigator.js';
12	import { probe } from '../page-adapter/probe.js';
13	import { createWatcher } from '../page-adapter/watcher.js';
14	import { mountSessionButton } from '../page-adapter/session-button.js';
15	import { mountSettingsModal } from '../page-adapter/settings-modal.js';
16	import { mountSessionDataModal } from '../page-adapter/session-data-modal.js';
17	import { dismissSplash, waitForSplashClear } from '../page-adapter/splash.js';
18	import { render } from '../conversation/phrases.js';
19	import { createOrchestrator } from '../app/orchestrator.js';
20	import { createSttPort } from '../speech/stt-port.js';
21	import { createRemoteTtsPort } from '../speech/remote-tts-port.js';
22	import { createPing } from '../speech/ping.js';
23	import { loadSettings } from '../settings/settings.js';
24	import { puzzleTag } from '../shared/urls.js';
25	
26	const TAG = '[CrosswordChat]';
27	let session = null; // { orchestrator, port }
28	let starting = false; // guards the async gap before `session` exists (button double-click)
29	// REQ-DIAG-001: in-memory diagnostics — every voice session run on THIS page load. Held only
30	// here, never persisted (REQ-NFR-002), and gone when the page reloads. `currentLog` is the
31	// active session's record; `sessionLogs` is the page's history for the "Send session data" dialog.
32	const sessionLogs = [];
33	let currentLog = null;
34	
35	function createPageClient() {
36	  let watcher = null;
37	  return {
38	    snapshot: async () => snapshot(document),
39	    enterAnswer: async (cells) => enterAnswer(document, cells),
40	    clearEntry: async (cellIndices) => clearEntry(document, cellIndices),
41	    selectClue: async (clueId) => ({ ok: selectClue(document, clueId) }),
42	    // Full-grid verdict (REQ-LIFE-005/006): the page rules with a popup — congrats
43	    // (snapshot.status 'solved') or "Keep trying". The orchestrator waits for one and
44	    // reacts; the negative one is clicked away so the board is usable again — the
45	    // splash dismisser already knows how to click a modal's Keep-trying/Play button.
46	    ruledWrong: async () => isRuledWrong(document),
47	    dismissVerdict: async () => dismissSplash(document, { waitMs: 1500 }),
48	    watch: async (cb) => {
49	      if (watcher) return;
50	      watcher = createWatcher(document, cb);
51	      watcher.start();
52	    },
53	    unwatch: async () => {
54	      watcher?.stop();
55	      watcher = null;
56	    },
57	    // Our own typing must not look like user activity (REQ-NAV-008).
58	    pauseWatch: () => watcher?.pause(),
59	    resumeWatch: () => watcher?.resume(),
60	    // A heard user command keeps NYT from auto-pausing a quiet puzzle (REQ-LIFE-017).
61	    keepAlive: () => keepAlive(document),
62	  };
63	}
64	
65	async function startSession() {
66	  if (session || starting) return; // duplicate START (e.g. double-click) — one session per page
67	  starting = true;
68	  try {
69	    const port = chrome.runtime.connect({ name: MSG.SESSION_PORT });
70	    const stt = createSttPort();
71	    const tts = createRemoteTtsPort(port);
72	    const settings = await loadSettings(); // REQ-NAV-012: options-page choices apply per session
73	    currentLog = { // REQ-DIAG-001/002: turns + the run context they only make sense against
74	      startedAt: Date.now(),
75	      version: chrome.runtime.getManifest().version,
76	      puzzle: puzzleTag(location.pathname),
77	      settings: { ...settings },
78	      entries: [],
79	    };
80	    sessionLogs.push(currentLog);
81	    if (settings.biasing && settings.biasing !== 'off') {
82	      // REQ-DIAG-002: did the biasing experiment actually engage? Only meaningful (and
83	      // only probed) when the setting asks for biasing at all.
84	      void stt.biasingAvailable().then((ok) => { if (currentLog) currentLog.onDevice = ok; });
85	    }
86	
87	    const orchestrator = createOrchestrator({
88	      tts,
89	      stt,
90	      pageClient: createPageClient(),
91	      settings,
92	      ping: createPing(), // REQ-SPCH-010: audible "mic open / reset" tick
93	
94	      ui: {
95	        caption: (role, text) => {
96	          if (!text) return;
97	          console.info(`${TAG} ${role === 'heard' ? `heard: “${text}”` : text}`); // REQ-SPCH-007/008
98	        },
99	        listening: (on) => console.debug(`${TAG} mic ${on ? 'on' : 'off'}`),
100	        // REQ-DIAG-001: append structured turns to the current session's in-memory record.
101	        diag: (entry) => { currentLog?.entries.push({ t: Date.now(), ...entry }); },
102	      },
103	      onEnd: () => {
104	        console.info(`${TAG} session ended`);
105	        session = null;
106	        currentLog = null; // REQ-DIAG-001: the next session starts a fresh record
107	        toggleButton.setActive(false);
108	        document.removeEventListener('keydown', onKeydown, true);
109	        try {
110	          port.disconnect(); // badge clears in the service worker
111	        } catch { /* already gone */ }
112	      },
113	    });
114	    session = { orchestrator, port };
115	    toggleButton.setActive(true);
116	
117	    // REQ-LIFE-015: Escape ends the session instantly, like the toggle. Only real
118	    // key presses count (isTrusted) — synthetic events can never end the session.
119	    // NYT binds Escape too (it opens rebus entry): during a session the key is OURS —
120	    // capture-phase on document runs before the app's delegated handler, and stopping
121	    // propagation keeps the rebus box from popping alongside the teardown.
122	    const onKeydown = (event) => {
123	      if (event.key === 'Escape' && event.isTrusted) {
124	        event.stopPropagation();
125	        event.preventDefault();
126	        orchestrator.stop();
127	      }
128	    };
129	    document.addEventListener('keydown', onKeydown, true);
130	
131	    port.onMessage.addListener((msg) => {
132	      if (msg?.type === MSG.CLOSE) orchestrator.stop(); // icon toggle / takeover
133	    });
134	    // Service worker died — an infrastructure abort, not a user stop (REQ-DIAG-002).
135	    port.onDisconnect.addListener(() => orchestrator.stop('worker-lost'));
136	
137	    // Surface the mic prompt (page origin) at a sane moment (REQ-SPCH-003); recognition
138	    // errors still flow through the machine if the user denies here. The preflight also
139	    // reports whether echo cancellation engaged — recorded for the log (REQ-DIAG-002).
140	    const mic = await stt.ensureMicPermission();
141	    if (currentLog && typeof mic?.echoCancellation === 'boolean') {
142	      currentLog.aec = mic.echoCancellation;
143	    }
144	
145	    // REQ-LIFE-016: the pre-puzzle splash ("Ready to start solving?") hides the board.
146	    // Click Play for the user; if the page insists on a real click, ask them to and
147	    // wait — the session then starts the moment the board appears.
148	    if (!(await dismissSplash(document))) {
149	      await tts.speak(render({ kind: 'splash' }));
150	      if (!(await waitForSplashClear(document))) {
151	        orchestrator.stop();
152	        return;
153	      }
154	    }
155	    await orchestrator.start();
156	  } finally {
157	    starting = false;
158	  }
159	}
160	
161	// The in-page split button (REQ-LIFE-012): the main half has the same semantics as the
162	// extension icon — start when idle (REQ-LIFE-001), instant silent stop mid-session
163	// (REQ-LIFE-002); the caret opens Settings and the voice-command reference (REQ-CMD-007).
164	// Settings opens a centred in-page modal that mirrors NYT's own Puzzle Settings popup
165	// (REQ-NAV-012) — no extension window; the extension icon's Settings route is unchanged.
166	// Help still opens an extension page, which only the worker can do (REQ-CMD-007). Mounts
167	// as soon as the NYT toolbar renders; quietly absent when it never does.
168	let settingsModal = null;
169	let sessionDataModal = null;
170	const toggleButton = mountSessionButton(document, {
171	  onToggle: () => {
172	    if (session) session.orchestrator.stop();
173	    else void startSession();
174	  },
175	  onSettings: () => {
176	    settingsModal = mountSettingsModal(document, { onClose: () => { settingsModal = null; } });
177	  },
178	  onHelp: () => chrome.runtime.sendMessage({ type: MSG.OPEN_HELP }).catch(() => {}),
179	  // REQ-DIAG-001: the in-page diagnostics dialog reads the in-memory session history.
180	  onSendData: () => {
181	    sessionDataModal = mountSessionDataModal(document, {
182	      getSessions: () => sessionLogs,
183	      onClose: () => { sessionDataModal = null; },
184	    });
185	  },
186	});
187	
188	// REQ-LIFE-008 made deterministic for the mic. The session already dies with the page, but
189	// don't rely on the browser's implicit teardown to free the device: `pagehide` fires on real
190	// unload AND on bfcache freeze (the page is suspended, not destroyed, and an open recognizer's
191	// mic can stay held). End the session on the way out — orchestrator.stop() synchronously aborts
192	// the in-flight recognizer, so the mic is released now, not whenever GC gets to the frozen page.
193	window.addEventListener('pagehide', () => {
194	  if (session) session.orchestrator.stop('page-hidden');
195	});
196	
197	chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
198	  switch (msg?.type) {
199	    case MSG.START:
200	      void startSession();
201	      sendResponse({ ok: true });
202	      break;
203	    case MSG.PING:
204	      sendResponse({ ok: true });
205	      break;
206	    case MSG.SNAPSHOT: // debugging (service-worker console)
207	      sendResponse(snapshot(document));
208	      break;
209	    case MSG.PROBE: // debugging (MT-01)
210	      sendResponse(probe(document));
211	      break;
212	    default:
213	      return false; // not ours
214	  }
215	  return false; // all responses are synchronous (writes happen via the in-page orchestrator)
216	});
217

file.content:
// Content script: hosts the whole conversation inside the puzzle page — brain, voice,
// and hands in one place. Speech-only by design: what was said/heard goes to the page
// console for debugging (REQ-SPCH-007/008). Inert until asked (REQ-NFR-004): the only
// load-time side effects are registering the message listener and placing the toolbar
// toggle button (REQ-LIFE-012 — the spec's one carve-out). The session dies with the
// page (reload/navigation) — that is intended (REQ-LIFE-008).

import { MSG } from '../shared/messages.js';
import { snapshot, isRuledWrong } from '../page-adapter/reader.js';
import { enterAnswer, clearEntry, keepAlive } from '../page-adapter/writer.js';
import { selectClue } from '../page-adapter/navigator.js';
import { probe } from '../page-adapter/probe.js';
import { createWatcher } from '../page-adapter/watcher.js';
import { mountSessionButton } from '../page-adapter/session-button.js';
import { mountSettingsModal } from '../page-adapter/settings-modal.js';
import { mountSessionDataModal } from '../page-adapter/session-data-modal.js';
import { dismissSplash, waitForSplashClear } from '../page-adapter/splash.js';
import { render } from '../conversation/phrases.js';
import { createOrchestrator } from '../app/orchestrator.js';
import { createSttPort } from '../speech/stt-port.js';
import { createRemoteTtsPort } from '../speech/remote-tts-port.js';
import { createPing } from '../speech/ping.js';
import { loadSettings } from '../settings/settings.js';
import { puzzleTag } from '../shared/urls.js';

const TAG = '[CrosswordChat]';
let session = null; // { orchestrator, port }
let starting = false; // guards the async gap before `session` exists (button double-click)
// REQ-DIAG-001: in-memory diagnostics — every voice session run on THIS page load. Held only
// here, never persisted (REQ-NFR-002), and gone when the page reloads. `currentLog` is the
// active session's record; `sessionLogs` is the page's history for the "Send session data" dialog.
const sessionLogs = [];
let currentLog = null;

function createPageClient() {
  let watcher = null;
  return {
    snapshot: async () => snapshot(document),
    enterAnswer: async (cells) => enterAnswer(document, cells),
    clearEntry: async (cellIndices) => clearEntry(document, cellIndices),
    selectClue: async (clueId) => ({ ok: selectClue(document, clueId) }),
    // Full-grid verdict (REQ-LIFE-005/006): the page rules with a popup — congrats
    // (snapshot.status 'solved') or "Keep trying". The orchestrator waits for one and
    // reacts; the negative one is clicked away so the board is usable again — the
    // splash dismisser already knows how to click a modal's Keep-trying/Play button.
    ruledWrong: async () => isRuledWrong(document),
    dismissVerdict: async () => dismissSplash(document, { waitMs: 1500 }),
    watch: async (cb) => {
      if (watcher) return;
      watcher = createWatcher(document, cb);
      watcher.start();
    },
    unwatch: async () => {
      watcher?.stop();
      watcher = null;
    },
    // Our own typing must not look like user activity (REQ-NAV-008).
    pauseWatch: () => watcher?.pause(),
    resumeWatch: () => watcher?.resume(),
    // A heard user command keeps NYT from auto-pausing a quiet puzzle (REQ-LIFE-017).
    keepAlive: () => keepAlive(document),
  };
}

async function startSession() {
  if (session || starting) return; // duplicate START (e.g. double-click) — one session per page
  starting = true;
  try {
    const port = chrome.runtime.connect({ name: MSG.SESSION_PORT });
    const stt = createSttPort();
    const tts = createRemoteTtsPort(port);
    const settings = await loadSettings(); // REQ-NAV-012: options-page choices apply per session
    currentLog = { // REQ-DIAG-001/002: turns + the run context they only make sense against
      startedAt: Date.now(),
      version: chrome.runtime.getManifest().version,
      puzzle: puzzleTag(location.pathname),
      settings: { ...settings },
      entries: [],
    };
    sessionLogs.push(currentLog);
    if (settings.biasing && settings.biasing !== 'off') {
      // REQ-DIAG-002: did the biasing experiment actually engage? Only meaningful (and
      // only probed) when the setting asks for biasing at all.
      void stt.biasingAvailable().then((ok) => { if (currentLog) currentLog.onDevice = ok; });
    }

    const orchestrator = createOrchestrator({
      tts,
      stt,
      pageClient: createPageClient(),
      settings,
      ping: createPing(), // REQ-SPCH-010: audible "mic open / reset" tick

      ui: {
        caption: (role, text) => {
          if (!text) return;
          console.info(`${TAG} ${role === 'heard' ? `heard: “${text}”` : text}`); // REQ-SPCH-007/008
        },
        listening: (on) => console.debug(`${TAG} mic ${on ? 'on' : 'off'}`),
        // REQ-DIAG-001: append structured turns to the current session's in-memory record.
        diag: (entry) => { currentLog?.entries.push({ t: Date.now(), ...entry }); },
      },
      onEnd: () => {
        console.info(`${TAG} session ended`);
        session = null;
        currentLog = null; // REQ-DIAG-001: the next session starts a fresh record
        toggleButton.setActive(false);
        document.removeEventListener('keydown', onKeydown, true);
        try {
          port.disconnect(); // badge clears in the service worker
        } catch { /* already gone */ }
      },
    });
    session = { orchestrator, port };
    toggleButton.setActive(true);

    // REQ-LIFE-015: Escape ends the session instantly, like the toggle. Only real
    // key presses count (isTrusted) — synthetic events can never end the session.
    // NYT binds Escape too (it opens rebus entry): during a session the key is OURS —
    // capture-phase on document runs before the app's delegated handler, and stopping
    // propagation keeps the rebus box from popping alongside the teardown.
    const onKeydown = (event) => {
      if (event.key === 'Escape' && event.isTrusted) {
        event.stopPropagation();
        event.preventDefault();
        orchestrator.stop();
      }
    };
    document.addEventListener('keydown', onKeydown, true);

    port.onMessage.addListener((msg) => {
      if (msg?.type === MSG.CLOSE) orchestrator.stop(); // icon toggle / takeover
    });
    // Service worker died — an infrastructure abort, not a user stop (REQ-DIAG-002).
    port.onDisconnect.addListener(() => orchestrator.stop('worker-lost'));

    // Surface the mic prompt (page origin) at a sane moment (REQ-SPCH-003); recognition
    // errors still flow through the machine if the user denies here. The preflight also
    // reports whether echo cancellation engaged — recorded for the log (REQ-DIAG-002).
    const mic = await stt.ensureMicPermission();
    if (currentLog && typeof mic?.echoCancellation === 'boolean') {
      currentLog.aec = mic.echoCancellation;
    }

    // REQ-LIFE-016: the pre-puzzle splash ("Ready to start solving?") hides the board.
    // Click Play for the user; if the page insists on a real click, ask them to and
    // wait — the session then starts the moment the board appears.
    if (!(await dismissSplash(document))) {
      await tts.speak(render({ kind: 'splash' }));
      if (!(await waitForSplashClear(document))) {
        orchestrator.stop();
        return;
      }
    }
    await orchestrator.start();
  } finally {
    starting = false;
  }
}

// The in-page split button (REQ-LIFE-012): the main half has the same semantics as the
// extension icon — start when idle (REQ-LIFE-001), instant silent stop mid-session
// (REQ-LIFE-002); the caret opens Settings and the voice-command reference (REQ-CMD-007).
// Settings opens a centred in-page modal that mirrors NYT's own Puzzle Settings popup
// (REQ-NAV-012) — no extension window; the extension icon's Settings route is unchanged.
// Help still opens an extension page, which only the worker can do (REQ-CMD-007). Mounts
// as soon as the NYT toolbar renders; quietly absent when it never does.
let settingsModal = null;
let sessionDataModal = null;
const toggleButton = mountSessionButton(document, {
  onToggle: () => {
    if (session) session.orchestrator.stop();
    else void startSession();
  },
  onSettings: () => {
    settingsModal = mountSettingsModal(document, { onClose: () => { settingsModal = null; } });
  },
  onHelp: () => chrome.runtime.sendMessage({ type: MSG.OPEN_HELP }).catch(() => {}),
  // REQ-DIAG-001: the in-page diagnostics dialog reads the in-memory session history.
  onSendData: () => {
    sessionDataModal = mountSessionDataModal(document, {
      getSessions: () => sessionLogs,
      onClose: () => { sessionDataModal = null; },
    });
  },
});

// REQ-LIFE-008 made deterministic for the mic. The session already dies with the page, but
// don't rely on the browser's implicit teardown to free the device: `pagehide` fires on real
// unload AND on bfcache freeze (the page is suspended, not destroyed, and an open recognizer's
// mic can stay held). End the session on the way out — orchestrator.stop() synchronously aborts
// the in-flight recognizer, so the mic is released now, not whenever GC gets to the frozen page.
window.addEventListener('pagehide', () => {
  if (session) session.orchestrator.stop('page-hidden');
});

chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
  switch (msg?.type) {
    case MSG.START:
      void startSession();
      sendResponse({ ok: true });
      break;
    case MSG.PING:
      sendResponse({ ok: true });
      break;
    case MSG.SNAPSHOT: // debugging (service-worker console)
      sendResponse(snapshot(document));
      break;
    case MSG.PROBE: // debugging (MT-01)
      sendResponse(probe(document));
      break;
    default:
      return false; // not ours
  }
  return false; // all responses are synchronous (writes happen via the in-page orchestrator)
});

